using System.Net;
using System.Text;
namespace HexLive.Identity;

internal static class AdminView
{
    internal static string E(string text) => WebUtility.HtmlEncode(text);
    internal static string Checks(string[] selected) => "<div class='permissions'>" + string.Join("", KeyStore.Permissions.Select(p => {
        var (title, description) = p switch {
            "game.play" => ("Играть", "Подключение к игровым серверам"),
            "bugs.create" => ("Сообщать о багах", "Создание отчётов во Flashback"),
            "bugs.read" => ("Читать баги", "Просмотр очереди и обсуждений"),
            "bugs.manage" => ("Управлять багами", "Обработка отчётов и статусов"),
            "server.admin" => ("Администрировать сервер", "Игровая админка и команды"),
            _ => ("Управлять ключами", "Выдача, отзыв и изменение прав")
        };
        return "<label class='permission'><input type='checkbox' name='permissions' value='" + p + "'" + (selected.Contains(p) ? " checked" : "") + "><span><strong>" + title + "</strong><small>" + description + "</small></span></label>";
    })) + "</div>";
    internal static IResult Page(string body, int status = 200) => Results.Content("<!doctype html><html lang='ru'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Ключи доступа · HexLive</title><style>" + Css + "</style></head><body><header class='topbar'><a class='brand' href='/'><span class='logo'>H</span>HexLive <span class='muted'>/</span> <span>Доступ</span></a><a class='external' href='https://flashback.62-146-235-120.sslip.io/'>Flashback ↗</a></header><main>" + body + "</main><footer>HexLive · Закрытое тестирование</footer></body></html>", "text/html; charset=utf-8", statusCode: status);
    internal static IResult Login(string csrf, string? error, int status) => Page("<section class='login panel'><div class='eyebrow'>ЕДИНЫЙ ДОСТУП</div><h1>Войти в админку</h1><p class='muted'>Управляйте ключами и правами участников<br>закрытого тестирования.</p>" + (error == null ? "" : "<div class='alert' role='alert'><strong>Не удалось войти</strong><p>" + E(error) + "</p></div>") + "<form method='post' action='/login'>" + csrf + "<label class='field'>Ключ доступа<input name='key' type='password' autocomplete='current-password' placeholder='hexlive_…' required></label><p class='hint'>Вставьте ключ целиком. Для входа нужно право «Управлять ключами».</p><button class='primary wide'>Войти</button></form><div class='login-note'>Один ключ — игра, отчёты о багах и администрирование. Доступ определяется выданными правами.</div></section>", status);
    internal static IResult Error(string text, int status) => Page("<section class='panel login'><div class='alert' role='alert'><strong>Не удалось выполнить действие</strong><p>" + E(text) + "</p></div><a class='button primary' href='/'>Вернуться к ключам</a></section>", status);
    internal static IResult Dashboard(KeyStore.Account[] accounts, string csrf, string currentId, string query, string notice)
    {
        var html = new StringBuilder("<div class='page-heading'><div><div class='eyebrow'>АДМИНИСТРИРОВАНИЕ</div><h1>Ключи доступа</h1><p class='muted'>Один ключ для всех сервисов. Права можно изменить в любой момент.</p></div><form method='post' action='/logout'>" + csrf + "<button>Выйти</button></form></div>");
        if (notice.Length > 0) html.Append("<div class='notice' role='status'>").Append(E(notice)).Append("</div>");
        html.Append("<div class='stats'><div><strong>").Append(accounts.Count(a => !a.Revoked)).Append("</strong><span>Активных ключей</span></div><div><strong>").Append(accounts.Count(a => a.Revoked)).Append("</strong><span>Отозвано</span></div><div><strong>6</strong><span>Отдельных прав</span></div></div><div class='workspace'><aside><section class='panel'><div class='section-title'><h2>Новый ключ</h2><span class='badge'>Выдача</span></div><p class='muted'>Укажите получателя и выберите, что ему доступно.</p><form method='post' action='/issue'>").Append(csrf).Append("<label class='field'>Название ключа<input name='name' maxlength='100' placeholder='Например, Анна — тестирование' required></label><label class='field'>Кто будет пользоваться<select name='subjectType'><option value='player'>Игрок</option><option value='agent'>Агент</option></select></label><fieldset><legend>Права доступа</legend>").Append(Checks(["game.play", "bugs.create"])).Append("</fieldset><button class='primary wide'>Выдать ключ</button><p class='hint'>Новый ключ будет показан один раз. Сохраните его перед передачей участнику.</p></form></section></aside><section class='key-list'><div class='list-heading'><h2>Выданные ключи</h2><span class='muted'>").Append(accounts.Length).Append(" всего</span></div><form class='search' method='get' action='/'><input name='q' aria-label='Поиск ключей' placeholder='Найти по имени…' value='").Append(E(query)).Append("'><button>Найти</button></form>");
        var visible = accounts.Where(a => a.Name.Contains(query, StringComparison.OrdinalIgnoreCase)).OrderBy(a => a.Revoked).ThenBy(a => a.Name).ToArray();
        if (visible.Length == 0) html.Append("<div class='panel empty'>Ключи не найдены. Попробуйте другое имя.</div>");
        foreach (var a in visible) {
            var hidden = csrf + "<input type='hidden' name='id' value='" + E(a.Id) + "'><input type='hidden' name='expectedRevision' value='" + a.Revision + "'>";
            html.Append("<article class='panel key-card'><div class='section-title'><h2>").Append(E(a.Name)).Append(a.Id == currentId ? " <span class='self'>Это вы</span>" : "").Append("</h2><span class='badge ").Append(a.Revoked ? "revoked" : "active").Append("'>").Append(a.Revoked ? "Отозван" : "Активен").Append("</span></div><p class='hint'>").Append(a.SubjectType == "agent" ? "Агент" : "Игрок").Append(" · Создан ").Append(a.Created.ToString("dd.MM.yyyy")).Append(" · ").Append(a.Permissions!.Length).Append(" из 6 прав</p>");
            if (!a.Revoked) html.Append("<form method='post' action='/permissions'>").Append(hidden).Append("<fieldset><legend>Права доступа</legend>").Append(Checks(a.Permissions)).Append("</fieldset><div class='save-row'><span class='hint'>Ключ останется прежним</span><button>Сохранить права</button></div></form>");
            else html.Append("<p class='muted'>Доступ закрыт. Чтобы вернуть его, выпустите новый ключ.</p>");
            html.Append("<details class='actions'><summary>Замена и отзыв ключа</summary><p class='hint'>Замена сохраняет участника и его права. Предыдущий ключ перестанет работать.</p><form method='post' action='/issue'>").Append(hidden).Append("<input type='hidden' name='name' value='").Append(E(a.Name)).Append("'><button>Выпустить замену</button></form>");
            if (!a.Revoked) html.Append("<form class='revoke-form' method='post' action='/revoke'>").Append(hidden).Append("<label class='confirm'><input type='checkbox' required>Подтверждаю отключение доступа по этому ключу</label><button class='danger'>Отозвать ключ</button></form>");
            html.Append("</details></article>");
        }
        return Page(html.Append("</section></div>").ToString());
    }
    internal static IResult Issued(string name, string key) => Page("<section class='panel login'><div class='eyebrow'>ГОТОВО</div><h1>Ключ выдан</h1><p class='muted'>Получатель: <strong>" + E(name) + "</strong></p><div class='notice'>Сохраните ключ сейчас — повторно посмотреть его не получится.</div><div class='secret'><code>" + E(key) + "</code></div><p class='hint'>Выделите ключ и скопируйте его. Передайте получателю лично: этот ключ даёт доступ к его аккаунту.</p><a class='button primary wide' href='/'>К списку ключей</a></section>");
    private const string Css = """
:root{color-scheme:dark;font-family:Inter,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;background:#111216;color:#f0f0f5;font-size:14px}*{box-sizing:border-box}body{margin:0}a{color:#b2a2ff;text-decoration:none}button,input,select{font:inherit}button,.button{display:inline-flex;align-items:center;justify-content:center;min-height:40px;border:1px solid #393a48;border-radius:9px;padding:10px 16px;background:#23242e;color:#f0f0f5;font-weight:600;cursor:pointer;transition:background .15s}button:hover,.button:hover{background:#30313f}button.primary,.button.primary{background:#b2a2ff;color:#191426;border-color:#b2a2ff}.primary:hover{background:#c3b7ff!important}.danger{color:#ee929f;border-color:#67404c;background:#312028}input:not([type=checkbox]),select{width:100%;min-height:44px;border:1px solid #363744;border-radius:9px;background:#111216;color:#f0f0f5;padding:11px 13px;outline:none}input::placeholder{color:#777b8e}input:focus,select:focus{border-color:#b2a2ff}*:focus-visible{outline:2px solid #b2a2ff;outline-offset:3px}input[type=checkbox]{accent-color:#b2a2ff;width:17px;height:17px;flex-shrink:0;margin:2px 0}.topbar{height:72px;display:flex;align-items:center;justify-content:space-between;padding:0 40px;background:#0d0e12;border-bottom:1px solid #2a2b35}.brand{display:flex;gap:14px;align-items:center;font-weight:650;color:#f0f0f5}.brand>span:last-child{font-weight:400}.logo{background:#2c2643;color:#b2a2ff;width:32px;height:32px;border:1px solid #554771;border-radius:9px;display:grid;place-items:center}.external{font-size:13px;color:#989aa9}main{max-width:1320px;padding:40px;margin:auto;min-height:calc(100vh - 130px)}h1{font-size:30px;letter-spacing:-.8px;margin:8px 0 12px}h2{font-size:17px;margin:0;overflow-wrap:anywhere}p{line-height:1.6;margin:10px 0 20px}.muted,.hint{color:#989aa9}.hint{font-size:12px;line-height:1.55}.eyebrow{font-size:10px;letter-spacing:1.8px;font-weight:700;color:#b2a2ff}.panel{border:1px solid #2a2b35;border-radius:15px;background:#191a21;padding:24px}.login{max-width:490px;margin:64px auto 30px;padding:34px}.login h1{font-size:29px}.field{display:flex;flex-direction:column;gap:9px;margin:20px 0;font-weight:550;font-size:13px}.wide{width:100%}.login-note{border-top:1px solid #2a2b35;margin-top:26px;padding-top:20px;color:#989aa9;font-size:12px;line-height:1.7}.alert{padding:16px;border:1px solid #70414d;border-radius:10px;background:#322029;color:#f4aeb8;margin:20px 0}.alert p{margin:6px 0 0;font-size:13px}.notice{border:1px solid #385a4d;background:#192d27;color:#99dfbf;border-radius:10px;padding:14px 18px;margin-bottom:24px;line-height:1.5}.page-heading,.section-title,.list-heading,.save-row{display:flex;justify-content:space-between;align-items:center;gap:16px}.page-heading{margin-bottom:28px}.page-heading p{margin-bottom:0}.stats{display:grid;grid-template-columns:repeat(3,1fr);border:1px solid #2a2b35;border-radius:12px;margin-bottom:32px;background:#15161c}.stats>div{padding:19px 24px;border-right:1px solid #2a2b35;display:flex;gap:14px;align-items:center}.stats>div:last-child{border:0}.stats strong{font-size:25px}.stats span{font-size:12px;color:#989aa9}.workspace{display:grid;grid-template-columns:365px minmax(0,1fr);gap:28px;align-items:start}.section-title h2{min-width:0}.badge{font-size:11px;border-radius:6px;padding:5px 9px;background:#2c2643;color:#b2a2ff;white-space:nowrap}.badge.active{color:#78cfab;background:#20382e}.badge.revoked{color:#a6a8b6;background:#2a2b35}.self{font-size:10px;color:#b2a2ff;white-space:nowrap}.permissions{display:grid;grid-template-columns:1fr 1fr;gap:9px}.permission{display:flex;align-items:start;gap:10px;padding:12px;border:1px solid #30313d;border-radius:9px;cursor:pointer;background:#15161c}.permission:has(input:checked){border-color:#615180;background:#262137}.permission:hover{border-color:#807197}.permission strong{display:block;font-size:12px;font-weight:550;line-height:1.4}.permission small{display:block;color:#989aa9;font-size:11px;line-height:1.5;margin-top:4px}aside .permissions{grid-template-columns:1fr}fieldset{border:0;padding:0;margin:22px 0}legend{font-size:12px;color:#989aa9;margin-bottom:12px}.key-card{margin-top:14px}.save-row .hint{margin:0}.actions{border-top:1px solid #2a2b35;margin-top:20px;padding-top:16px}.actions summary{cursor:pointer;color:#989aa9;font-size:12px}.actions[open] summary{color:#b2a2ff;margin-bottom:16px}.confirm{display:flex;gap:10px;align-items:center;font-size:12px;color:#c7a4aa;margin:20px 0 12px}.revoke-form{margin-top:20px;border-top:1px solid #39303a}.list-heading{margin:3px 0 18px}.search{display:flex;gap:8px}.search input{min-width:0}.secret{padding:20px;background:#111216;border:1px solid #494054;border-radius:10px;overflow-wrap:anywhere;line-height:1.8;user-select:all;color:#d0c4ff}.empty{text-align:center;color:#989aa9;margin-top:16px}footer{text-align:center;color:#6f7284;font-size:11px;padding:18px}@media(max-width:950px){.workspace{grid-template-columns:310px minmax(0,1fr)}.permissions{grid-template-columns:1fr}main{padding:28px 22px}.topbar{padding:0 22px}.stats>div{padding:16px}}@media(max-width:720px){.workspace{grid-template-columns:1fr}.page-heading{align-items:flex-start}.stats>div{flex-direction:column;gap:6px;align-items:start;padding:14px}.stats span{font-size:11px}.login{margin:25px auto;padding:24px}.panel{padding:20px}h1{font-size:26px}.brand{gap:9px}.topbar{height:62px}.save-row{flex-wrap:wrap}.page-heading p{font-size:13px}main{padding:26px 16px}.permissions{grid-template-columns:1fr}.external{font-size:12px}}@media(prefers-reduced-motion:reduce){*{transition:none!important}}
""";
}
